    employee_no: "GC024",
    password: "971110106343",
    device_id: "android"
};

msg.headers = {
    "Content-Type": "application/json",
    "app-key": "3aCGH6bNVav8acPvzA6/THVfK8rXIExI4d2RD8ZzoYo"
};

return msg;

msg.api_token = msg.payload.data.api_token;
msg.page = 0;
msg.allResults = [];

msg.headers = {
    "app-key": "3aCGH6bNVav8acPvzA6/THVfK8rXIExI4d2RD8ZzoYo",
    "app-token": msg.api_token
};

msg.url = "https://apis.hrhl.com.my/api/v1.0/diagnosis.json?page=0";

return msg;

if (!msg.payload || !msg.payload.data) {
    node.error("Invalid API response", msg);
    return null;
}

let data = msg.payload.data;

if (!msg.allResults) {
    msg.allResults = [];
}

let currentResults = Array.isArray(data.result) ? data.result : [];

//node.warn("PAGE = " + msg.page);
//node.warn("RESULT COUNT PAGE INI = " + currentResults.length);

msg.allResults = msg.allResults.concat(currentResults);

//node.warn("TOTAL COLLECTED = " + msg.allResults.length);

if (msg.total_page === undefined) {
    msg.total_page = data.total_page;
}

// kalau nak page 0 sampai 5
if (msg.page < msg.total_page) {
    msg.page = msg.page + 1;

    msg.url = "https://apis.hrhl.com.my/api/v1.0/diagnosis.json?page=" + msg.page;

    // SET BALIK REQUEST HEADER
    msg.headers = {
        "app-key": "3aCGH6bNVav8acPvzA6/THVfK8rXIExI4d2RD8ZzoYo",
        "app-token": msg.api_token
    };

    // GET request, kosongkan payload
    msg.payload = "";

    return [msg, null];
} else {
    msg.payload = {
        total_page: msg.total_page,
        total_records: msg.allResults.length,
        result: msg.allResults
    };

    return [null, msg];
}

if (msg.payload && Array.isArray(msg.payload.result)) {
    msg.payload = msg.payload.result
        .sort((a, b) => a.id - b.id)
        .map(x => ({
            id: x.id,
            name: x.name
        }));
}

return msg;
